    adcs_mat3_t identity;

    /* 1. Null check */
    if ((vectors == NULL) || (weights == NULL) || (information == NULL)) {
        return ADCS_E_NULL;
    }

    /* 2. Count range check [2, 32] */
    if (count < 2 || count > 32) {
        return ADCS_E_RANGE;
    }

    /* 3. Initialize H to zero */
    h_sum.m[0][0] = 0.0; h_sum.m[0][1] = 0.0; h_sum.m[0][2] = 0.0;
    h_sum.m[1][0] = 0.0; h_sum.m[1][1] = 0.0; h_sum.m[1][2] = 0.0;
    h_sum.m[2][0] = 0.0; h_sum.m[2][1] = 0.0; h_sum.m[2][2] = 0.0;

    /* Identity matrix for reuse */
    identity = adcs_mat3_identity();

    /* 4. Loop through observations */
    for (k = 0; k < count; ++k) {
        double w_k = weights[k];

        /* Check weight validity: finite and positive */
        if (!isfinite(w_k) || w_k <= 0.0) {
            goto failure_zero;
        }

        /* Check vector finiteness */
        if (!adcs_is_finite_vec3(&vectors[k])) {
            goto failure_zero;
