    // This handles the "failure output zero" contract automatically 
    // because any early return will leave it zeroed, 
    // and normal flow overwrites it correctly.
    for (size_t i = 0; i < 3; i++) {
        for (size_t j = 0; j < 3; j++) {
            information->m[i][j] = 0.0;
        }
    }

    double weight_sum = 0.0;
    adcs_mat3_t weighted_outer_sum = {{{0}}};
    adcs_vec3_t u_norm;

