        weighted_outer_sum.m[2][0] += w * u_norm.z * u_norm.x;
        weighted_outer_sum.m[2][1] += w * u_norm.z * u_norm.y;
        weighted_outer_sum.m[2][2] += w * u_norm.z * u_norm.z;
    }

    // 4. Calculate H = Sum(w)*I - Sum(w * u * u^T)
    information->m[0][0] = weight_sum - weighted_outer_sum.m[0][0];
    information->m[0][1] = -weighted_outer_sum.m[0][1];
    information->m[0][2] = -weighted_outer_sum.m[0][2];

    information->m[1][0] = -weighted_outer_sum.m[1][0];
    information->m[1][1] = weight_sum - weighted_outer_sum.m[1][1];
    information->m[1][2] = -weighted_outer_sum.m[1][2];

    information->m[2][0] = -weighted_outer_sum.m[2][0];
    information->m[2][1] = -weighted_outer_sum.m[2][1];
    information->m[2][2] = weight_sum - weighted_outer_sum.m[2][2];

    // 5. Check for finite values (NaN/Inf check)
    for (size_t i = 0; i < 3; i++) {
        for (size_t j = 0; j < 3; j++) {
            if (!isfinite(information->m[i][j])) {
                // Reset to zero on failure
                for (size_t r = 0; r < 3; r++)
                    for (size_t c = 0; c < 3; c++)
                        information->m[r][c] = 0.0;
                return ADCS_E_NOT_FINITE;
            }
        }
    }

    return ADCS_OK;
}

